from model import load_payload
from transform import transform

class TestJsonUsers(unittest.TestCase):
    def test_records_sorted_and_merged(self):
        payload = {'json_text': json.dumps([
            {'id': 2, 'name': 'B', 'email': 'b@x'},
            {'id': 1, 'name': 'A'},
            {'id': 2, 'email': 'b2@x'},
        ])}
        contract = {'name': 'json_users', 'inputs': ['x']}
        r = transform([payload], contract)
        self.assertEqual(set(r), {'name', 'result'})
        recs = r['result']['records']
        self.assertEqual([x['id'] for x in recs], ['1', '2'])
        self.assertEqual(recs[1]['name'], 'B')
        self.assertEqual(recs[1]['email'], 'b2@x')

    def test_joined_date_formats(self):
        payload = {'json_text': json.dumps([
            {'id': 'a', 'joined': '2024-01-03'},
            {'id': 'b', 'joined': '03/01/2024'},
        ])}
        r = transform([payload], {'name': 'json_users', 'inputs': ['x']})
        recs = r['result']['records']
        self.assertEqual(recs[0]['joined'], '2024-01-03')
        self.assertEqual(recs[1]['joined'], '2024-01-03')

    def test_alias_fields(self):
        payload = {'json_text': json.dumps([
            {'user_id': 7, 'full_name': 'N', 'mail': 'm@x', 'joined_at': '2024-01-03'},
        ])}
        r = transform([payload], {'name': 'json_users', 'inputs': ['x']})
        rec = r['result']['records'][0]
        self.assertEqual(rec['id'], '7')
        self.assertEqual(rec['name'], 'N')
        self.assertEqual(rec['email'], 'm@x')

    def test_empty(self):
        r = transform([{'json_text': '[]'}], {'name': 'json_users', 'inputs': ['x']})
        self.assertEqual(r['result']['records'], [])

    def test_bool_id_rejected(self):
        payload = {'json_text': json.dumps([{'id': True}])}
        with self.assertRaises(ValueError):
            transform([payload], {'name': 'json_users', 'inputs': ['x']})

if __name__ == '__main__':
    unittest.main()
